SELECT point_code, last_at FROM (SELECT m.point_code AS point_code, (SELECT a.at FROM progress_answer a WHERE a.learner = m.learner AND a.point_code = m.point_code AND a.subject_id = m.subject_id ORDER BY a.id DESC LIMIT 1) AS last_at FROM progress_mastery m WHERE m.learner = :learner AND m.mastered = 1 AND m.subject_id = CAST(:subject_id AS INTEGER)) WHERE last_at IS NOT NULL AND substr(last_at, 1, 10) < :cutoff ORDER BY last_at ASC, point_code ASC LIMIT CAST(:limit AS INTEGER)
